        <div class="actions"><button onclick="go('explore')">Explorar</button></div>
      </div>
      <div class="card">
        <h3>Publicar um serviço</h3>
        <p>Anuncie o serviço que você oferece.</p>
        <div class="actions"><button onclick="go('publish')">Publicar</button></div>
